export async function initializeFonts(pdfDoc) {


	if(!getFonts("helvetica")){}
	
	  const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica)
	  const helveticaBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold)
  
	  let TimesRomanBold = await pdfDoc.embedFont(StandardFonts.TimesRomanBold);
	  let TimesRomanItalic = await pdfDoc.embedFont(StandardFonts.TimesRoman);
	  
	  updFonts("helvetica",helveticaFont)
	  updFonts("helveticaBold",helveticaBold)
	  updFonts("TimesRomanBold",TimesRomanBold)
	  updFonts("TimesRomanItalic",TimesRomanItalic)
  
	
  
	  const promises =  ObjectKeys(fonstList).map(async (fnt)=>{
		let fontUrl = getStore(fonstList[fnt]);
		const fontBytes =  await fetch(fontUrl).then((res) => res.arrayBuffer());
		const fRdy = await pdfDoc.embedFont(fontBytes, { subset: true });
		updFonts(fnt,fRdy)
	  })      
	  await Promise.all(promises);
	
	  return getFonts();
  
  }


  


