export const drawRuler = (firstPage, height, font, posX, posY) =>{

	posY = posY || 30;
	posX = posX || 30;
  
	Array.from(Array(200).keys()).map(g=>{
	  firstPage?.drawText((g+1)*5%10? (g+1)*5 -5 + "" :"|", {
		x: (g)*5,
		y: height - posY ,
		size: 4,
		font: font,      
		color:  rgb(0, 0, 0)
	  });
  
	})
  
  
	Array.from(Array(800).keys()).map((g)=>{
  
	  let line00 =  " ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ----" 
	  let txt =  g%4!==0 ? "- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - ": line00; 
  
	  let color =  g%4!==0 ? rgb(1,.647,0)  :rgb(0.4, 0.81, 0.21);
  
	  if(g%2!==0){
		txt = (height - (g+1)*1.25 + 2).toFixed(1)  +" -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --"
		color = rgb(0, 0, 0) ;
		//color =  rgb(.4,.47,.40);
	  }
  
	  
  
	  
	  firstPage?.drawText(txt + "", {
		x: posX,
		y: (g)*1.25,
		size: 3,
		font: font,      
		color:  color 
	  });
  
	})
  
  
  
  }
  