import React, { useEffect, useState } from "react";



import { getStore, updStore, gen16CodeId,  fetchEncryptStream,  ObjectKeys, parseFloatToDecimal, qryStore, generateComprobanteId, parseDateMMDDYYYY, dayNames2ES, parseDate, lblTaxField, lblTaxList, compareJSON, getWeekDetailsByDay, parseDateShort, deepCompare, deepCompareByF, getWeek } from "../../../stores/Utils";

import {  TextInput_Cmpt, SvgIcon_Cmpt, DropDwnPicker_Cmpt } from "../../../components";


import "./dashboard.css"
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import { PayStubInfoPdf } from "../../Inventory/services/export_service";
import { Paystub2AccountantEmployee_Cmpt } from "..";
import { NavLink } from "react-router-dom";
import { get_compById } from "../services/server_fetching";


const TextInput = TextInput_Cmpt();

const Paystub2AccountantEmployee = Paystub2AccountantEmployee_Cmpt();

const DropDwnPicker = DropDwnPicker_Cmpt();


const Svg = SvgIcon_Cmpt();



const frmNm = "view_paystub_employee";
const frmNmW2Manual = "paystub_W2_manual";


const flds2Watch = ["w2Taxes", "grossPay", "otherDeductions", "weekNo"]

const ViewPaystubEmployee  = ({data,  item}) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);


	useEffect(() => {
		if (!initialize) {
			updStore("cmpByPayStub", null)
			setInitialize(true);
			let frm2 = getStore(frmNm) || {};

			
			if(getStore("employees_ids")?.[getStore(frmNm)?.["employeeId"]]?.hasW2 && !frm2.w2Taxes){
				updFrm("w2Taxes",getStore("global_account_params")?.w2_params );
			}

			if(!frm2.weekNo){
				if(frm2.datePeriod){
					let wkk = getWeek(frm2.datePeriod)
					updFrm("weekNo", "Wk_"+ wkk );
				}
			}

			if(!frm2.grossPay){
				let hourlyP = hourlyParse(getStore(frmNm)?.["hourly"],getStore(frmNm)?.["payrate"], getStore(frmNm)?.["lunchDuration"], getStore(frmNm)?.["hasOvertime"])
				let grossPay = hourlyP.regularPayment + hourlyP.overtimePayment;
				updFrm("grossPay",grossPay );
			}

			// fetchCmptId();
			
			set_obs(gen16CodeId())
		}
	});



	const fetchCmptId = async (f, v, k) => {
		let dd = await get_compById(getStore(frmNm)?.["comprobanteId"], getStore(frmNm)?.["employeeId"])
		let info = dd && dd[ObjectKeys(dd)[0]];
		updStore("cmpByPayStub", info)

	}

	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		set_obs(gen16CodeId())
	};





	
	
	const updTaxW2 = async (f) => {
		let ffm = getStore(frmNm) || {};
		let commonflds = {
			businessId:  getStore("profileUser")?.businessId,
			year: (new Date(ffm["date"])).getFullYear(),
			epaystubId: ffm["epaystubId"],
		}
	
		let diff = compareJSON(flds2Watch,getStore(frmNm),getStore(frmNm + "_bck") )


		let bdyq2 = {...getStore(qryStore())?.upd_employee_paystub};
		bdyq2.params = commonflds;
		bdyq2.data2update= diff.data

		// console.log(bdyq2)
		fetch2Server(bdyq2);


	}


	

	


	const fetch2Server = async (bdyq2) => {

		
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td) {
		
			setTimeout(() => {
				updStore(frmNm, null)
				updStore(frmNmW2Manual, null)
				data?.modalID && CloseModal({id:data?.modalID});
			}, 400);
		}
	}


	
	const close =  () => {
		data?.modalID && CloseModal({id:data?.modalID});
	}		

	const send2pdf = async () => {
	
		PayStubInfoPdf(getStore(frmNm))
	}

	let hourlyP = hourlyParse(getStore(frmNm)?.["hourly"],getStore(frmNm)?.["payrate"], getStore(frmNm)?.["lunchDuration"], getStore(frmNm)?.["hasOvertime"])

	let employeeDt = getStore("employees_ids")?.[getStore(frmNm)?.["employeeId"]];
	let grossPay = hourlyP.regularPayment + hourlyP.overtimePayment;


	let diff = compareJSON(flds2Watch,getStore(frmNm),getStore(frmNm + "_bck") );

	


	const updComprobante = async (v,d) => {
		let ffm = getStore(frmNm) || {};
		let commonflds = {
			businessId:  getStore("profileUser")?.businessId,
			year: (new Date(ffm["date"])).getFullYear(),
			epaystubId: ffm["epaystubId"],
		}
		let bdyq2 = {...getStore(qryStore())?.upd_employee_paystub};
		bdyq2.params = commonflds;
		bdyq2.data2update= {comprobanteId: v, document: d}
		
		fetch2Server(bdyq2);
		
	}


	const send2Books = async (bdyq2) => {
	
		

		let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{
				
			}};
			
			modaldata["content"] = <Paystub2AccountantEmployee 
				item={getStore(frmNm)} 
				confirm={updComprobante}
			/>
			OpenModal(modaldata);
	}


	
	const addOtherDeductionModal = async (bdyq2) => {
		updStore(frmNmED, {});
		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "40vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{
			
		}};
		
		modaldata["content"] = <OthersDeductions 
			item={getStore(frmNm)} 
			confirm={addOtherDeductio}
		/>
		OpenModal(modaldata);
	}

	const addOtherDeductio = (v) => {
		let ffm = getStore(frmNm) || {};
		let otherDeductions = ffm.otherDeductions || {};
		otherDeductions[v.otherDeduction] = v;
		updFrm("otherDeductions",otherDeductions);
	}


	let cmpByPayStubMayor = getStore(frmNm).comprobanteId && getStore("cmpByPayStubMayor")?.[getStore(frmNm).comprobanteId];


	let isClosed =  !(cmpByPayStubMayor && ObjectKeys(cmpByPayStubMayor).length);
	


	return (
		<div
		style={{
			maxHeight: "96vh",
			minHeight: "80vh",
			width: "1280px",
			minWidth: "1040px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 25px"
		}}
		className="payStub "
		>
			<div className="_dsplFlx ">
				<p className="form_title">
					Nomina
				</p>
				{isClosed?  
				<div className="_dsplFlx spaceAround flxWrp card_2_dark"  >
					<p className="group_title addBtn purple" onClick={send2Books}>
						Enviar a contabilidad
					</p>
				</div>
				:<div style={{padding: "16px 0 0 12px"}}>
					<NavLink to={{
						pathname: "/accounting-ledger" ,
						search: `?cId=${getStore(frmNm)?.["comprobanteId"]}`
					}}>
						<div className="comprobante_id" onClick={()=>close()}>
								{getStore(frmNm).comprobanteId}
						</div>
					</NavLink>
				</div>}
				<div className="flexSpace"/>
				
				<div className="employee_name">
					{employeeDt?.name}
				</div>
				<div className="icon" onClick={send2pdf} style={{margin:"0px 10px 0px 10px"}}>
					<Svg name={"printer"} color={"#282828"}/>
				</div>
			</div>

			<div className="_dsplFlx " style={{margin:"10px 10px 10px 0"}}>
				<div className="flexSpace"/>
				<div >
					<p className="label">Fecha</p>
					<p className="value2Upd">{parseDate(getStore(frmNm)?.["date"]*1)} </p>
				</div>
				<div className="flexSpace"/>
				<div >
					<p className="label">Periodo</p>
					<p className="value2Prd ">{parseWeekrange(getStore(frmNm)?.["datePeriod"]*1)} </p>
				</div>
				

				<div className="flexSpace"/>
				<div>
					<p className="label">Pago X Hora</p>
					<p className="value2Upd">{(getStore(frmNm)?.["payrate"]*1).toFixed(2)} </p>
				</div>
				<div className="flexSpace"/>
				<div>
					<p className="label">Lunch Duration</p>
					<p className="value2Upd">{(getStore(frmNm)?.["lunchDuration"]*1).toFixed(1)} </p>
				</div>
				<div className="flexSpace"/>
				<div style={{margin:"30px 0px 0px 0"}}>
					<div className="_dsplFlx " >
						<div className="icon_revision"  >
							<Svg 
								name={!getStore(frmNm)?.["hasOvertime"] ? "alert":"check_circle"} 
								color={!getStore(frmNm)?.["hasOvertime"] ? "var(--hrm_palette-selected-nav-text)":"var(--hrm_palette-success-fg)"}
							/>
						</div>
						<span className={`checklabel`}>
							{"Overtime"}
						</span>
					</div>
				</div>
				
				<div className="flexSpace"/>
				
			
			</div>
			<div className="_dsplFlx spaceAround flxWrp card_2_dark"  style={{margin: "56px 0 56px"}} >
			{getStore(frmNm)?.["hourly"] && ObjectKeys(getStore(frmNm)?.["hourly"]).map((day,inD)=>{
				let dayItm = getStore(frmNm)?.["hourly"]?.[day];
				
				return (
					<TimeUpdateDay
						key={day}
						dayName={day}
						index={inD}
						data={dayItm}
						payrate={getStore(frmNm)?.["payrate"]*1}
						lunch={getStore(frmNm)?.["lunchDuration"]*1}
						overtime={getStore(frmNm)?.["overtime"]}
						
					/>
				)
			})}
			</div>
			
			{ isClosed? 
			<div className="_dsplFlx spaceAround flxWrp "  style={{margin: "2px 0 26px"}} >
				<p className="group_title addBtn purple" onClick={addOtherDeductionModal}>
						Add other Deductions
					</p>
				
			</div>
			 :null}
			
			
			{(hourlyP.regularPayment + hourlyP.overtimePayment)>0 && !employeeDt?.hasW2? 
				<Paydetail 
					hourlyP={hourlyP} 
					otherDeductions={getStore(frmNm)?.otherDeductions} 
					updform={updFrm}
					isClosed={isClosed}
				/>
			:null}


			


			{(hourlyP.regularPayment + hourlyP.overtimePayment)>0 && employeeDt?.hasW2? 
				<div className="_dsplFlx spaceAround flxWrp card_2_dark"  >
					<div className="flexSpace"/>
					<PaydetailV 
						hourlyP={hourlyP} 
						w2Taxes={getStore(frmNm)?.["w2Taxes"]}
						otherDeductions={getStore(frmNm)?.otherDeductions} 
					/>
					<div className="flexSpace"/>
					<PayGroosTaxDt 
						grossPay={grossPay} 
						w2Taxes={getStore(frmNm)?.["w2Taxes"]} 
						isCompleted={getStore(frmNm)?.comprobanteId}
						otherDeductions={getStore(frmNm)?.otherDeductions} 
						updform={updFrm}
						isClosed={isClosed}
					/>
					<div className="flexSpace"/>
				</div>
			:null}


			
			

			{isClosed && diff.hasChange ? 
			<div className="_dsplFlx spaceAround flxWrp card_2_dark"  >
				<p className="group_title addBtn purple" onClick={updTaxW2}>
					Actualizar
				</p>
			</div>
			:<div style={{padding: 40}} className="_dsplFlx spaceAround flxWrp card_2_dark" />}

		</div>
	);
};

export default ViewPaystubEmployee;





