const PayGroosTaxDt  = ({
	grossPay,
	isCompleted,
	w2Taxes,
	otherDeductions,
	updform,
	isClosed
 }) => {
	const [obs, set_obs] = useState(0);
	const updObserve = () =>{
		set_obs(gen16CodeId());
	}

	let totalTax = sumTax(w2Taxes,grossPay);

	let totalOtherDd = sumOtherDd(otherDeductions);

	return (
		<div className=" " >
			<div >
			{lblTaxList.map(fldTx=>{
				return (
					<PayTaxItm
						key={fldTx}
						fldTx={fldTx}
						grossPay={grossPay}
						updObserve={updObserve}
						isCompleted={isCompleted}
					/>
				)
			})}
			</div>
			{otherDeductions && ObjectKeys(otherDeductions).map((oDId,inD)=>{
				
				const deleteItm = () =>{
					let ffm = getStore(frmNm) || {};
					let otherDeductions = ffm.otherDeductions || {};
					delete otherDeductions[oDId];
					updform("otherDeductions",otherDeductions);
				}
				let oDItm = otherDeductions?.[oDId];
				
				return (
					<div className="_dsplFlx " key={oDId}>
						<span className={`checklabel`}>
							{oDId + ": "}
						</span>
						<div className="date2Upd " >
							{(oDItm.amount*1)?.toFixed(2)}
						</div>
						<div className="flexSpace"/>
						{isClosed ? 
						<div className="icon " onClick={deleteItm}>
							<Svg name={"outline_delete"} color={"#c62828"} size={20}/>
						</div>
						:null}
					</div>

				)
			})}

			<div className="separator payroll"/>
			<div className="_dsplFlx " >
				<span className={`checklabel`}>
					{"Total Deductions:"}
				</span>
				<div className="date2Upd " >
					${( totalTax - totalOtherDd).toFixed(2)}
				</div>
			</div>
		</div>
	)
 }


let disableEdit = {
	"medicareTax":0,
	"socialSecurity":0
}


 const PayTaxItm  = ({
	fldTx,
	grossPay,
	updObserve,
	isCompleted
 }) => {


	

	const updPerc =  () => {
		if(!disableEdit[fldTx] && !isCompleted){
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{
				updObserve()
			}  };
			
			modaldata["content"] = <UpdatePercentTax fldTx={fldTx} grossPay={grossPay}/>
			OpenModal(modaldata);
		}
	}

	return (
		<div className="_dsplFlx " onClick={updPerc}>
			<span className={`checklabel`}>
				{lblTaxField[fldTx]}: 	
			</span>
			<div className="date2Upd " >
				{(getStore(frmNm)?.w2Taxes?.[fldTx]?.percent*1).toFixed(2)}%
			</div>
			<span className={`checklabel`} style={{marginLeft:19}}>
				${(grossPay * getStore(frmNm)?.w2Taxes?.[fldTx]?.percent/100).toFixed(2)}
			</span>
		</div>
	)
}






