const Paydetail  = ({
	hourlyP,
	otherDeductions,
	updform,
	isClosed
 }) => {


	let othDDT = (sumOtherDd(otherDeductions)*1);
	let grossPay = (hourlyP.regularPayment + hourlyP.overtimePayment)*1;
	return (
		<div className="_dsplFlx "   >
				<div className="flexSpace"/>
				<div>
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Regular Payments: "}
						</span>
						<div className="date2Upd " >
							{hourlyP.regularPayment.toFixed(2)}
						</div>
					</div>
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Regular Hours: "}
						</span>
						<div className="date2Upd " >
							{(hourlyP.regularHours/60).toFixed(2)}
						</div>
					</div>
					
				
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Overtime Payments: "}
						</span>
						<div className="date2Upd " >
							{hourlyP.overtimePayment.toFixed(2)}
						</div>
					</div>
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Overtime Hours: "}
						</span>
						<div className="date2Upd " >
							{(hourlyP.overtimeHours/60).toFixed(2)}
						</div>
					</div>
				</div>
				<div className="flexSpace"/>
				<div>
					
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Gross Payment: "}
						</span>
						<div className="date2Upd " >
							{(grossPay).toFixed(2)}
						</div>
					</div>
					{otherDeductions && ObjectKeys(otherDeductions).map((oDId,inD)=>{
				
						const deleteItm = () =>{
							let ffm = getStore(frmNm) || {};
							let otherDeductions = ffm.otherDeductions || {};
							delete otherDeductions[oDId];
							updform("otherDeductions",otherDeductions);
						}
						let oDItm = otherDeductions?.[oDId];
						
						return (
							<div className="_dsplFlx " key={oDId}>
								<span className={`checklabel`}>
									{oDId + ": "}
								</span>
								<div className="date2Upd " >
									{(oDItm.amount*1)?.toFixed(2)}
								</div>
								<div className="flexSpace"/>
								{isClosed ? 
								<div className="icon " onClick={deleteItm}>
									<Svg name={"outline_delete"} color={"#c62828"} size={20}/>
								</div>
								:null}
							</div>

						)
					})}

					
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Net Payment: "}
						</span>
						<div className="date2Upd " >
							{(grossPay + othDDT).toFixed(2)}
						</div>
					</div>
				</div>
				<div className="flexSpace"/>
			</div>
	)

 }








