const PaydetailV  = ({
	hourlyP,
	w2Taxes,
	otherDeductions
 }) => {

	let grossPay = hourlyP.regularPayment + hourlyP.overtimePayment;
	let totalTax = sumTax(w2Taxes,grossPay)

	let totalOtherDd = sumOtherDd(otherDeductions);

	return (
		<div className=" "  >
				
				
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Regular Payments: "}
						</span>
						<div className="date2Upd " >
							${hourlyP.regularPayment.toFixed(2)}
						</div>
					</div>
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Regular Hours: "}
						</span>
						<div className="date2Upd " >
							{(hourlyP.regularHours/60).toFixed(2)}
						</div>
					</div>
					
				
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Overtime Payments: "}
						</span>
						<div className="date2Upd " >
							${hourlyP.overtimePayment.toFixed(2)}
						</div>
					</div>
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Overtime Hours: "}
						</span>
						<div className="date2Upd " >
							{(hourlyP.overtimeHours/60).toFixed(2)}
						</div>
					</div>
			
					
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Gross Payment: "}
						</span>
						<div className="date2Upd " >
							${grossPay.toFixed(2)}
						</div>
					</div>
					<div className="separator payroll"/>
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Net Payment: "}
						</span>
						<div className="date2Upd " >
							${(grossPay -  totalTax + totalOtherDd).toFixed(2)}
						</div>
					</div>
			</div>
	)

 }









