export const parseTimeH  = ( v)  => {
	if(!v){
		return null;
	}
	let hh = Math.floor(v/60);
	let mm = v - (hh*60);
	return  `${hh>9?hh:"0"+hh}:${mm>9?mm:"0"+mm}`;
}





export const hourlyParse  = ( hourly , payrate, lunch, overtime)  => {

	let hoursTt = 0;
	let hoursAfterLunch = 0;
	let overtimeHours = 0;
	let payrateMin = payrate/60;
	

	ObjectKeys(hourly).map((day,inD)=>{
		if(hourly?.[day]?.active){

			let minT = hourly?.[day]?.end - hourly?.[day]?.start;
			
			hoursTt += minT
			hoursAfterLunch +=minT - lunch*1;
		}
	})
	
	if(overtime && hoursAfterLunch>2400){
		overtimeHours = hoursAfterLunch - 2400;
		hoursAfterLunch = 2400;
	}

	
	let info = {
		hoursTt,
		regularHours: hoursAfterLunch,
		regularPayment: hoursAfterLunch*payrateMin,
		overtimeHours,
		overtimePayment: overtimeHours*payrateMin*1.5
	}
	return info;

}

		












const UpdatePercentTax  = ({
	fldTx,
	grossPay
	
 }) => {

	const [obs, set_obs] = useState(0);
	const [initialize, setInitialize] = useState(false);
	

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			let frm2 = getStore(frmNm) || {};
			
			if(!frm2.w2Taxes?.[fldTx]?.amount){
				let amm = frm2.w2Taxes?.[fldTx]?.percent / 100 * grossPay;
				updFrmw2Taxes("amount", amm)
				
			}
			
			set_obs(gen16CodeId())
		}
	});

	

	const updAmount = (v) =>{
		let percent = v * 100 / grossPay;
		updFrmw2Taxes("percent", percent);
		updFrmw2Taxes("amount", v*1);
	}

	const updPercent = (v) =>{
		let amm = v / 100 * grossPay;
		updFrmw2Taxes("amount", amm);
		updFrmw2Taxes("percent", v*1);
	}
	
	const updFrmw2Taxes = (f, v) => {
		let frm2 = getStore(frmNm) || {};
		let w2Taxes = getStore(frmNm)?.w2Taxes;
		w2Taxes[fldTx][f] = v;
		frm2.w2Taxes = w2Taxes;
		updStore(frmNm, frm2);
		set_obs(gen16CodeId());
	};



	return (
		<div
		style={{
			maxHeight: "76vh",
			minHeight: "43vh",
			width: "540px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 25px"
		}}
		className="payStub "
		>
			<div className="_dsplFlx ">
				<p className="form_title">
					{lblTaxField[fldTx]}: 	
				</p>
				<div className="flexSpace"/>
				
				
			</div>
			<div className="_dsplFlx spaceAround flxWrp card_2_dark"  style={{margin: "26px 0 26px"}} >
				<div className="flexSpace"/>
				<TextInput  
					init={getStore(frmNm)?.w2Taxes?.[fldTx]?.percent} 
					label={"Tax %"} 
					width={120} 
					type={"number"}
					updChanges={(e)=>updPercent(e)}
				/>
				<div className="flexSpace"/>
				<TextInput  
					init={getStore(frmNm)?.w2Taxes?.[fldTx]?.amount} 
					label={"Amount"} 
					width={120} 
					type={"number"}
					updChanges={(e)=>updAmount(e)}
				/>
				<div className="flexSpace"/>
			</div>
		</div>
	)

 }















export const parseWeekrange = (datePeriod, ddmm)=>{
	let wP = getWeekDetailsByDay(datePeriod)
	let _2hr = 60000* 120;

	return ddmm? `${parseDateMMDDYYYY(wP.stWk)} - ${parseDateMMDDYYYY(wP.endWk - _2hr)}`: `${parseDateShort(wP.stWk)} - ${parseDateShort(wP.endWk - _2hr)}`
} 





export const sumTax = (W2,grossPay ) =>{
	let balance = 0;
	W2 && ObjectKeys(W2).map((dyId, Ind)=>{
		let item = W2[dyId];
		let amount = item.amount ? item.amount  : item.percent / 100 * grossPay;
		balance +=	amount;
	})
	return balance;
  }



  export const sumOtherDd = (W2 ) =>{
	let balance = 0;
	W2 && ObjectKeys(W2).map((dyId, Ind)=>{
		let item = W2[dyId];
		let amount = item.amount*1;
		balance +=	amount;
	})
	return balance;
  }





